intentos.respuesta_cruda:
{
  "sql": "SELECT t1.product_category_name_english, ROUND(SUM(CASE WHEN t2.payment_installments > 1 THEN 1 ELSE 0 END) * 100.0 / COUNT(t1.product_id), 2) AS pct_pagos_plazos FROM product_category_translation t1 INNER JOIN products p ON t1.product_category_name = p.product_category_name INNER JOIN order_items oi ON p.product_id = oi.product_id INNER JOIN order_payments t2 ON oi.order_id = t2.order_id WHERE t2.payment_type != 'not_defined' GROUP BY t1.product_category_name_english HAVING COUNT(t1.product_id) >= 100 ORDER BY pct_pagos_plazos DESC LIMIT 1"
}
